-- Migration 037: 50 more real, local Georgia organizations, all distinct from
-- migration-008 (first 24) and migration-036 (next 50). Broad category coverage
-- including art, tech, disaster, and animals, spread across Atlanta, Savannah,
-- Macon, Athens, Columbus, Decatur, Alpharetta, Marietta, Clarkston, and
-- statewide. Each org was researched individually and its website/volunteer page
-- verified. Pure inserts with fixed ids - safe to re-run, existing rows untouched.

insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
values
  -- ART
  ('c3000000-0000-4000-8000-000000000001', null, 'Woodruff Arts Center', 'One of the largest arts centers in the country, home to the High Museum of Art, Atlanta Symphony Orchestra, and Alliance Theatre, relying on volunteers across its campus and events.', 'https://www.woodruffcenter.org', 'https://www.google.com/s2/favicons?domain=www.woodruffcenter.org&sz=128', 'art', array['recurring', 'creative work'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000002', null, 'Alliance Theatre', 'The leading professional theater in the Southeast, based at the Woodruff Arts Center, supported by the volunteer-run Alliance Theatre Guild.', 'https://alliancetheatre.org', 'https://www.google.com/s2/favicons?domain=alliancetheatre.org&sz=128', 'art', array['recurring', 'creative work'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000003', null, 'Telfair Museums', 'Savannah''s art museum network, where volunteer docents train to lead tours and welcome visitors across three historic sites.', 'https://www.telfair.org', 'https://www.google.com/s2/favicons?domain=www.telfair.org&sz=128', 'art', array['recurring', 'leadership role'], false, false, 16, 'United States', 'GA', 'Savannah', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000004', null, 'Atlanta Contemporary', 'A nonprofit contemporary art center in Atlanta making current art accessible to all, with volunteers helping at events, exhibitions, and the welcome desk.', 'https://atlantacontemporary.org', 'https://www.google.com/s2/favicons?domain=atlantacontemporary.org&sz=128', 'art', array['recurring', 'creative work'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000005', null, 'Center for Puppetry Arts', 'The largest organization in the United States dedicated to the art of puppetry, offering performances, a museum, and education programs in Atlanta.', 'https://puppet.org', 'https://www.google.com/s2/favicons?domain=puppet.org&sz=128', 'art', array['recurring', 'creative work', 'family friendly'], false, false, 13, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000006', null, 'Spelman College Museum of Fine Art', 'The only museum in the nation emphasizing art by and about women of the African Diaspora, with a Museum Ambassador volunteer program open to the public.', 'https://www.spelman.edu', 'https://www.google.com/s2/favicons?domain=www.spelman.edu&sz=128', 'art', array['recurring', 'leadership role'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000007', null, 'Atlanta Artists Center', 'A nonprofit supporting visual artists in Atlanta through exhibitions, education, and community programs, run with the help of member and volunteer support.', 'https://atlantaartistscenter.org', 'https://www.google.com/s2/favicons?domain=atlantaartistscenter.org&sz=128', 'art', array['recurring', 'creative work'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- ANIMALS
  ('c3000000-0000-4000-8000-000000000008', null, 'Georgia Aquarium', 'One of the largest aquariums in the world, an Atlanta nonprofit dedicated to conservation, research, and education, with volunteer roles across more than 30 departments.', 'https://www.georgiaaquarium.org', 'https://www.google.com/s2/favicons?domain=www.georgiaaquarium.org&sz=128', 'animals', array['recurring', 'leadership role'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000009', null, 'Zoo Atlanta', 'A nonprofit zoo and conservation organization in Grant Park, engaging volunteers to educate guests and help safeguard endangered species.', 'https://zooatlanta.org', 'https://www.google.com/s2/favicons?domain=zooatlanta.org&sz=128', 'animals', array['recurring', 'leadership role'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000010', null, 'Canine Assistants', 'An Alpharetta nonprofit that raises and places service dogs with people who have physical disabilities, epilepsy, or diabetes, relying on volunteers to foster, socialize, and train dogs.', 'https://www.canineassistants.org', 'https://www.google.com/s2/favicons?domain=www.canineassistants.org&sz=128', 'animals', array['recurring', 'family friendly'], false, false, 16, 'United States', 'GA', 'Alpharetta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000011', null, 'Chastain Horse Park', 'A nonprofit therapeutic riding center in the heart of Atlanta providing equine-assisted therapy and lessons, with volunteers supporting riders of all abilities.', 'https://www.chastainhorsepark.org', 'https://www.google.com/s2/favicons?domain=www.chastainhorsepark.org&sz=128', 'animals', array['recurring', 'outdoors'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- GARDENING
  ('c3000000-0000-4000-8000-000000000012', null, 'Atlanta Botanical Garden', 'A nonprofit garden in Midtown Atlanta devoted to plant collections, conservation, and education, with Discovery and library volunteer roles year round.', 'https://atlantabg.org', 'https://www.google.com/s2/favicons?domain=atlantabg.org&sz=128', 'gardening', array['outdoors', 'recurring', 'family friendly'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000013', null, 'State Botanical Garden of Georgia', 'A University of Georgia garden in Athens focused on native plants, conservation, and horticulture, welcoming volunteers to help curators and in the gardens.', 'https://botgarden.uga.edu', 'https://www.google.com/s2/favicons?domain=botgarden.uga.edu&sz=128', 'gardening', array['outdoors', 'recurring', 'physical work'], false, false, 14, 'United States', 'GA', 'Athens', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000014', null, 'Wylde Center', 'A Decatur-area nonprofit stewarding neighborhood greenspaces and gardens, where volunteers help in the nursery, the plant market, and at community events.', 'https://www.wyldecenter.org', 'https://www.google.com/s2/favicons?domain=www.wyldecenter.org&sz=128', 'gardening', array['outdoors', 'physical work', 'good for crews'], false, false, 12, 'United States', 'GA', 'Decatur', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000015', null, 'Historic Oakland Foundation', 'The nonprofit that preserves Atlanta''s historic Oakland Cemetery, where more than 300 volunteers work in the gardens, lead tours, and staff events.', 'https://www.oaklandcemetery.com', 'https://www.google.com/s2/favicons?domain=www.oaklandcemetery.com&sz=128', 'gardening', array['outdoors', 'physical work', 'recurring'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- ENVIRONMENT
  ('c3000000-0000-4000-8000-000000000016', null, 'Georgia Conservancy', 'A statewide nonprofit protecting Georgia''s land, water, and coast since 1967, running hands-on service days at state parks like Sweetwater Creek and Panola Mountain.', 'https://georgiaconservancy.org', 'https://www.google.com/s2/favicons?domain=georgiaconservancy.org&sz=128', 'environment', array['outdoors', 'physical work', 'good for crews'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000017', null, 'Park Pride', 'An Atlanta nonprofit that helps communities improve their parks and greenspaces through volunteerism, advocacy, and capital projects.', 'https://parkpride.org', 'https://www.google.com/s2/favicons?domain=parkpride.org&sz=128', 'environment', array['outdoors', 'physical work', 'good for crews'], false, false, 12, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000018', null, 'Keep Georgia Beautiful Foundation', 'A statewide foundation supporting 70-plus local affiliates that fight litter, promote recycling, and beautify communities across Georgia.', 'https://keepgeorgiabeautiful.org', 'https://www.google.com/s2/favicons?domain=keepgeorgiabeautiful.org&sz=128', 'environment', array['outdoors', 'good for crews', 'family friendly'], false, false, 12, 'United States', 'GA', 'Georgia', true, true, 'both', false),
  -- FOOD
  ('c3000000-0000-4000-8000-000000000019', null, 'America''s Second Harvest of Coastal Georgia', 'A volunteer-driven hunger-relief food bank serving 21 counties in coastal Georgia from Savannah, distributing food through a wide network of partners.', 'https://helpendhunger.org', 'https://www.google.com/s2/favicons?domain=helpendhunger.org&sz=128', 'food', array['good for crews', 'family friendly'], false, false, 12, 'United States', 'GA', 'Savannah', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000020', null, 'Middle Georgia Community Food Bank', 'A Macon food bank feeding neighbors across middle Georgia since 1981, where hundreds of volunteers a year pack and distribute food to people in need.', 'https://mgcfb.org', 'https://www.google.com/s2/favicons?domain=mgcfb.org&sz=128', 'food', array['good for crews', 'family friendly'], false, false, 12, 'United States', 'GA', 'Macon', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000021', null, 'Our Daily Bread Community Kitchen', 'An Athens community kitchen, part of Downtown Ministries, serving more than 500 guests a week facing homelessness and poverty with the help of volunteer groups.', 'https://downtownministries.org', 'https://www.google.com/s2/favicons?domain=downtownministries.org&sz=128', 'food', array['good for crews', 'recurring'], false, false, 14, 'United States', 'GA', 'Athens', true, true, 'both', false),
  -- COMMUNITY
  ('c3000000-0000-4000-8000-000000000022', null, 'New American Pathways', 'An Atlanta nonprofit that helps refugees and Georgia thrive, serving thousands of new Americans each year through resettlement, employment, and education programs.', 'https://newamericanpathways.org', 'https://www.google.com/s2/favicons?domain=newamericanpathways.org&sz=128', 'community', array['recurring', 'counts for school hours'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000023', null, 'Friends of Refugees', 'A Clarkston nonprofit supporting the refugees resettled in one of the most diverse square miles in America through employment, wellness, and youth programs.', 'https://friendsofrefugees.com', 'https://www.google.com/s2/favicons?domain=friendsofrefugees.com&sz=128', 'community', array['recurring', 'family friendly', 'counts for school hours'], false, false, 14, 'United States', 'GA', 'Clarkston', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000024', null, 'Nicholas House', 'The only shelter in Atlanta that houses whole homeless families together, helping them reach self-sufficiency, with thousands of volunteer hours served each year.', 'https://nicholashouse.org', 'https://www.google.com/s2/favicons?domain=nicholashouse.org&sz=128', 'community', array['recurring', 'good for crews', 'family friendly'], false, false, 13, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000025', null, 'Atlanta Community ToolBank', 'A nonprofit tool-lending library that equips other charities and volunteer groups with tools for service projects, run with the help of warehouse volunteers.', 'https://www.atlantatoolbank.org', 'https://www.google.com/s2/favicons?domain=www.atlantatoolbank.org&sz=128', 'community', array['good for crews', 'physical work'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000026', null, 'United Ministries of Savannah', 'The interfaith nonprofit that runs the Emmaus House soup kitchen and day services in downtown Savannah, serving breakfast and essentials to neighbors in need.', 'https://unitedministriessavannah.org', 'https://www.google.com/s2/favicons?domain=unitedministriessavannah.org&sz=128', 'community', array['good for crews', 'recurring'], false, false, 16, 'United States', 'GA', 'Savannah', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000027', null, 'Kate''s Club', 'An Atlanta nonprofit offering free grief support to children, teens, and families who have experienced the death of someone close, powered by trained volunteers.', 'https://www.katesclub.org', 'https://www.google.com/s2/favicons?domain=www.katesclub.org&sz=128', 'community', array['recurring', 'creative work'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000028', null, 'Latin American Association', 'An Atlanta nonprofit empowering Latino families across Georgia with education, workforce, and family-support services, welcoming bilingual and general volunteers.', 'https://thelaa.org', 'https://www.google.com/s2/favicons?domain=thelaa.org&sz=128', 'community', array['recurring', 'counts for school hours'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- EDUCATION
  ('c3000000-0000-4000-8000-000000000029', null, 'Big Brothers Big Sisters of the Heart of Georgia', 'A Macon-based mentoring nonprofit that matches vetted volunteer mentors one-to-one with children across central Georgia at no cost to families.', 'https://bbbsheartga.org', 'https://www.google.com/s2/favicons?domain=bbbsheartga.org&sz=128', 'education', array['recurring', 'leadership role', 'counts for school hours'], false, false, 16, 'United States', 'GA', 'Macon', true, true, 'ongoing', false),
  ('c3000000-0000-4000-8000-000000000030', null, '100 Black Men of Atlanta', 'A mentoring and education nonprofit whose members and volunteers guide underserved Atlanta youth toward college through its flagship Project Success program.', 'https://100blackmen-atlanta.org', 'https://www.google.com/s2/favicons?domain=100blackmen-atlanta.org&sz=128', 'education', array['recurring', 'leadership role', 'counts for school hours'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'ongoing', false),
  ('c3000000-0000-4000-8000-000000000031', null, 'Ferst Readers', 'A Georgia early-literacy nonprofit that mails a free book each month to enrolled children under five, powered by local all-volunteer Community Action Teams.', 'https://ferstreaders.org', 'https://www.google.com/s2/favicons?domain=ferstreaders.org&sz=128', 'education', array['recurring', 'family friendly'], false, false, 13, 'United States', 'GA', 'Georgia', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000032', null, 'Books for Africa', 'The largest shipper of donated books to Africa, with an Atlanta fulfillment center where volunteers sort and pack books by category and age level.', 'https://www.booksforafrica.org', 'https://www.google.com/s2/favicons?domain=www.booksforafrica.org&sz=128', 'education', array['good for crews', 'counts for school hours', 'family friendly'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000033', null, 'Literacy Action', 'Founded in 1968, the largest nonprofit provider of free adult basic education in Georgia, teaching literacy and life skills to undereducated Atlanta adults.', 'https://literacyaction.org', 'https://www.google.com/s2/favicons?domain=literacyaction.org&sz=128', 'education', array['recurring', 'counts for school hours'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'ongoing', false),
  -- MEDICINE
  ('c3000000-0000-4000-8000-000000000034', null, 'American Cancer Society Hope Lodge Atlanta', 'A free home away from home for cancer patients and caregivers who travel to Atlanta for treatment, where volunteers cook meals and welcome guests.', 'https://www.cancer.org', 'https://www.google.com/s2/favicons?domain=www.cancer.org&sz=128', 'medicine', array['recurring', 'family friendly', 'good for crews'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000035', null, 'MedShare', 'An Atlanta-founded global health nonprofit that recovers surplus medical supplies and equipment for communities in need, with volunteers sorting supplies (youth 10-17 welcome with a parent form).', 'https://www.medshare.org', 'https://www.google.com/s2/favicons?domain=www.medshare.org&sz=128', 'medicine', array['good for crews', 'family friendly'], false, false, 10, 'United States', 'GA', 'Decatur', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000036', null, 'Bert''s Big Adventure', 'An Atlanta nonprofit that gives children with chronic and terminal illnesses and their families a magical trip to Walt Disney World plus year-round support.', 'https://bertsbigadventure.org', 'https://www.google.com/s2/favicons?domain=bertsbigadventure.org&sz=128', 'medicine', array['recurring', 'family friendly'], false, false, 21, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000037', null, 'CHRIS 180', 'One of the Southeast''s leading mental-health, child-welfare, and family-service nonprofits, providing trauma-informed care and school-based programs across metro Atlanta.', 'https://chris180.org', 'https://www.google.com/s2/favicons?domain=chris180.org&sz=128', 'medicine', array['recurring', 'good for crews'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- SENIORS
  ('c3000000-0000-4000-8000-000000000038', null, 'Alzheimer''s Association, Georgia Chapter', 'The Georgia chapter of the Alzheimer''s Association, supporting families affected by dementia through programs, support groups, advocacy, and awareness events.', 'https://www.alz.org', 'https://www.google.com/s2/favicons?domain=www.alz.org&sz=128', 'seniors', array['recurring', 'leadership role'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- SPORTS
  ('c3000000-0000-4000-8000-000000000039', null, 'YMCA of Metro Atlanta', 'A network of community YMCAs across metro Atlanta offering youth sports, swim, and wellness programs, staffed in part by volunteer coaches and program helpers.', 'https://www.ymcaatlanta.org', 'https://www.google.com/s2/favicons?domain=www.ymcaatlanta.org&sz=128', 'sports', array['recurring', 'leadership role', 'family friendly'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000040', null, 'Girls on the Run of Atlanta', 'A physical-activity-based youth development program that uses running and social-emotional learning to build confidence in girls ages 8 to 14, led by volunteer coaches.', 'https://www.girlsontherunatlanta.org', 'https://www.google.com/s2/favicons?domain=www.girlsontherunatlanta.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'ongoing', false),
  ('c3000000-0000-4000-8000-000000000041', null, 'First Tee - Metro Atlanta', 'A youth development nonprofit that uses the game of golf to teach character and life skills, relying on volunteer coaches and mentors (no golf experience required).', 'https://firstteeatlanta.org', 'https://www.google.com/s2/favicons?domain=firstteeatlanta.org&sz=128', 'sports', array['recurring', 'leadership role', 'outdoors'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'ongoing', false),
  -- MUSIC
  ('c3000000-0000-4000-8000-000000000042', null, 'Georgia Symphony Orchestra', 'A Marietta-based orchestra and home of the Georgia Youth Symphony Orchestra, the largest youth orchestra program in the Southeast, supported by event volunteers.', 'https://www.georgiasymphony.org', 'https://www.google.com/s2/favicons?domain=www.georgiasymphony.org&sz=128', 'music', array['recurring', 'creative work'], false, false, 14, 'United States', 'GA', 'Marietta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000043', null, 'ANAM Georgia', 'The Agape National Academy of Music, a youth development nonprofit using music and the arts to engage young people across metro Atlanta, seeking volunteer music teachers and mentors.', 'https://anamgeorgia.org', 'https://www.google.com/s2/favicons?domain=anamgeorgia.org&sz=128', 'music', array['recurring', 'creative work', 'counts for school hours'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- FAITH
  ('c3000000-0000-4000-8000-000000000044', null, 'The Salvation Army of Metro Atlanta', 'A faith-based nonprofit serving 13 metro Atlanta counties with shelter, meals, youth programs, and holiday assistance, offering one-time and ongoing volunteer roles.', 'https://southernusa.salvationarmy.org/metro-atlanta/', 'https://www.google.com/s2/favicons?domain=southernusa.salvationarmy.org&sz=128', 'faith', array['good for crews', 'family friendly', 'recurring'], false, false, 13, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000045', null, 'Valley Rescue Mission', 'A Christ-centered nonprofit in Columbus serving people experiencing homelessness and addiction since 1963 with shelter, meals, and recovery programs.', 'https://www.valleyrescuemission.org', 'https://www.google.com/s2/favicons?domain=www.valleyrescuemission.org&sz=128', 'faith', array['good for crews', 'recurring', 'family friendly'], false, false, 14, 'United States', 'GA', 'Columbus', true, true, 'both', false),
  -- VETERANS
  ('c3000000-0000-4000-8000-000000000046', null, 'Wounded Warrior Project', 'A national veterans service organization with an Atlanta office supporting the well-being of post-9/11 veterans and their families through programs and events.', 'https://www.woundedwarriorproject.org', 'https://www.google.com/s2/favicons?domain=www.woundedwarriorproject.org&sz=128', 'veterans', array['recurring', 'good for crews'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- DISASTER RELIEF
  ('c3000000-0000-4000-8000-000000000047', null, 'Team Rubicon', 'A veteran-led disaster-response nonprofit whose volunteers, known as Greyshirts, saw downed trees, muck out flooded homes, and tarp roofs after storms across Georgia.', 'https://teamrubiconusa.org', 'https://www.google.com/s2/favicons?domain=teamrubiconusa.org&sz=128', 'disaster', array['physical work', 'good for crews', 'leadership role'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000048', null, 'Inspiritus', 'A faith-rooted Atlanta nonprofit that guides people from crisis to resilience, mobilizing volunteers for disaster clean-up, rebuilding, and refugee resettlement across Georgia.', 'https://weinspirit.org', 'https://www.google.com/s2/favicons?domain=weinspirit.org&sz=128', 'disaster', array['physical work', 'good for crews', 'recurring'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- TECH
  ('c3000000-0000-4000-8000-000000000049', null, 'Goodie Nation', 'An Atlanta tech nonprofit connecting diverse founders and social entrepreneurs to resources, and linking tech-company employees to K-12 tech education volunteer roles.', 'https://goodienation.org', 'https://www.google.com/s2/favicons?domain=goodienation.org&sz=128', 'tech', array['recurring', 'leadership role'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c3000000-0000-4000-8000-000000000050', null, 'Girls Who Code', 'A national nonprofit closing the gender gap in technology, running free after-school coding clubs led by volunteer facilitators, including many across Georgia.', 'https://girlswhocode.com', 'https://www.google.com/s2/favicons?domain=girlswhocode.com&sz=128', 'tech', array['recurring', 'leadership role', 'counts for school hours'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'both', false)
