insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('c4000000-0000-4000-8000-000000000001', 'c3000000-0000-4000-8000-000000000001', 'Usher and Assist at Arts Center Events', 'art', 'Volunteers help welcome and seat guests, assist at performances and exhibitions, and support events across the Woodruff Arts Center campus, home to the High Museum, the symphony, and the Alliance Theatre. It is a great way to be around world-class art and performance while you help. Roles range from single events to a regular schedule.', array['recurring', 'creative work'], 16, false, false, true, '3-4 hrs', 'https://www.woodruffcenter.org/volunteer/', 'https://www.woodruffcenter.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000002', 'c3000000-0000-4000-8000-000000000002', 'Join the Alliance Theatre Guild', 'art', 'Volunteers with the Alliance Theatre Guild support the Southeast''s leading theater by helping at productions, education programs, and community events. If you love theater, it is a way to be part of the action behind the curtain. Guild membership rewards an ongoing commitment through the season.', array['recurring', 'creative work'], 16, false, false, true, '2-4 hrs', 'https://alliancetheatre.org/content/the-alliance-theatre-guild', 'https://alliancetheatre.org/content/the-alliance-theatre-guild', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000003', 'c3000000-0000-4000-8000-000000000003', 'Train as a Museum Docent in Savannah', 'art', 'Volunteers train to become docents who lead tours and welcome visitors across Telfair Museums'' three historic Savannah sites, with new docent classes each spring and fall. It is a great fit if you love art and public speaking. Docents commit to a couple of years of active service after training.', array['recurring', 'leadership role'], 16, false, false, true, '2-3 hrs / week', 'https://www.telfair.org/volunteers/', 'https://www.telfair.org/volunteers/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('c4000000-0000-4000-8000-000000000004', 'c3000000-0000-4000-8000-000000000004', 'Help Make Contemporary Art Accessible', 'art', 'Volunteers set up for events, photograph exhibitions and programs, and greet patrons at the Welcome Desk at Atlanta Contemporary, which asks volunteers to be 18 or older. It is ideal if you have a background or interest in contemporary or studio art. Roles are flexible and event-based.', array['recurring', 'creative work'], 18, false, false, true, '2-3 hrs', 'https://atlantacontemporary.org/get-involved/volunteer', 'https://atlantacontemporary.org/get-involved/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000005', 'c3000000-0000-4000-8000-000000000005', 'Volunteer at the Center for Puppetry Arts', 'art', 'Volunteers help welcome guests, support workshops, and assist with performances and the museum at the largest puppetry organization in the country. Volunteers 18 and up can serve on their own, while ages 13 to 17 need a signed parent permission slip. It is a uniquely creative and family-friendly place to give time.', array['recurring', 'creative work', 'family friendly'], 13, false, false, true, '2-3 hrs', 'https://puppet.org/support-us/become-a-volunteer/', 'https://puppet.org/support-us/become-a-volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000006', 'c3000000-0000-4000-8000-000000000006', 'Become a Museum Ambassador at Spelman', 'art', 'Volunteers serve as Museum Ambassadors at the Spelman College Museum of Fine Art, helping engage audiences with art by and about women of the African Diaspora. The program is open to college students and the general public. It is a meaningful role if you care about representation in the arts.', array['recurring', 'leadership role'], 16, false, false, true, '2-3 hrs', 'https://www.spelman.edu/museum-of-fine-art/join-and-give/volunteer.html', 'https://www.spelman.edu/museum-of-fine-art/join-and-give/volunteer.html', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000007', 'c3000000-0000-4000-8000-000000000007', 'Support Local Artists', 'art', 'Volunteers help hang shows, staff receptions, and run programs at the Atlanta Artists Center, a nonprofit supporting visual artists in the city. If you enjoy the gallery scene, it is a friendly, creative place to give a few hours. Roles range from single events to ongoing help.', array['recurring', 'creative work'], 16, false, false, true, '2-3 hrs', 'https://atlantaartistscenter.org/wp/volunteer/', 'https://atlantaartistscenter.org/wp/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000008', 'c3000000-0000-4000-8000-000000000008', 'Volunteer at Georgia Aquarium', 'animals', 'Volunteers inspire millions of guests a year by sharing their passion for the aquatic world, with roles spread across more than 30 departments at Georgia Aquarium. The general volunteer program is open to those 18 and up. It is a top pick if you love marine life and conservation.', array['recurring', 'leadership role'], 18, false, false, true, '4 hrs / shift', 'https://www.georgiaaquarium.org/volunteer-programs/', 'https://www.georgiaaquarium.org/volunteer-programs/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000009', 'c3000000-0000-4000-8000-000000000009', 'Help Guests Learn at Zoo Atlanta', 'animals', 'Volunteers help educate guests, support events, and inspire visitors to care about endangered species at Zoo Atlanta. You start by submitting an application and attending an orientation. It is a great fit if you love animals and enjoy talking with the public.', array['recurring', 'leadership role'], 18, false, false, true, '4 hrs / shift', 'https://zooatlanta.org/support/volunteer-opportunities/', 'https://zooatlanta.org/support/volunteer-opportunities/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000010', 'c3000000-0000-4000-8000-000000000010', 'Raise or Socialize a Service Dog', 'animals', 'Volunteers help raise, foster, groom, and socialize service dogs in training with Canine Assistants, whose greatest need is fostering young dogs for a few nights or weeks at a time. It is a hands-on way to help someone with a disability gain independence. Home visits and outings are part of the fun.', array['recurring', 'family friendly'], 16, false, false, true, 'Varies', 'https://www.canineassistants.org/', 'https://www.canineassistants.org/', '2026-01-01T00:00:00Z', 'Alpharetta', 'GA'),
  ('c4000000-0000-4000-8000-000000000011', 'c3000000-0000-4000-8000-000000000011', 'Sidewalk for Therapeutic Riding', 'animals', 'Volunteers lead horses and walk alongside riders during therapy and lessons at Chastain Horse Park, supporting children and adults in life-changing sessions. No horse experience is needed - orientation and training are provided. It is a joyful, hands-on role that helps both people and animals.', array['recurring', 'outdoors'], 14, false, false, true, '2-3 hrs', 'https://www.chastainhorsepark.org/volunteer', 'https://www.chastainhorsepark.org/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000012', 'c3000000-0000-4000-8000-000000000012', 'Guide Visitors at the Botanical Garden', 'gardening', 'Discovery volunteers engage visitors of all ages about the Atlanta Botanical Garden''s plant collections and conservation work, with shifts available Tuesday through Sunday. Volunteers commit to at least two shifts a month, and library roles are also available. It is a beautiful place to spend a recurring shift.', array['outdoors', 'recurring', 'family friendly'], 16, false, false, true, '3-4 hrs', 'https://atlantabg.org/volunteer/', 'https://atlantabg.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000013', 'c3000000-0000-4000-8000-000000000013', 'Help Curators in the Garden', 'gardening', 'Volunteers help curators plant, weed, and care for native and endangered species at the State Botanical Garden of Georgia in Athens, learning horticulture as they go. Expect real, hands-on outdoor work. It is a great fit if you want to build gardening skills while you serve.', array['outdoors', 'recurring', 'physical work'], 14, false, false, true, '2-3 hrs', 'https://botgarden.uga.edu/', 'https://botgarden.uga.edu/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('c4000000-0000-4000-8000-000000000014', 'c3000000-0000-4000-8000-000000000014', 'Work in the Wylde Center Gardens', 'gardening', 'Volunteers help seed, pot, water, and tend plants in the nursery, at the plant market, and in neighborhood greenspaces stewarded by the Wylde Center near Decatur. It is welcoming to first-timers and easy to do as a group. Shifts are often posted through Hands On Atlanta and the newsletter.', array['outdoors', 'physical work', 'good for crews'], 12, false, false, true, '2-3 hrs', 'https://www.wyldecenter.org/volunteer/', 'https://www.wyldecenter.org/volunteer/', '2026-01-01T00:00:00Z', 'Decatur', 'GA'),
  ('c4000000-0000-4000-8000-000000000015', 'c3000000-0000-4000-8000-000000000015', 'Garden and Guide Tours at Oakland', 'gardening', 'Volunteers work in the gardens, welcome visitors, and lead tours at Atlanta''s historic Oakland Cemetery during three-hour workdays held throughout the year. No experience is needed, and it is a great way to learn gardening and local history at once. All willing hands are welcome.', array['outdoors', 'physical work', 'recurring'], 14, false, false, true, '3 hrs', 'https://www.oaklandcemetery.com/volunteer', 'https://www.oaklandcemetery.com/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000016', 'c3000000-0000-4000-8000-000000000016', 'Join a State Park Service Day', 'environment', 'Volunteers join Georgia Conservancy service days at parks like Sweetwater Creek and Panola Mountain, adding trail blazes and removing debris and trash from the land and creeks. Projects are group-friendly and outdoors. It is a satisfying way to protect places that generations of Georgians enjoy.', array['outdoors', 'physical work', 'good for crews'], 14, false, false, true, '3-4 hrs', 'https://georgiaconservancy.org/', 'https://georgiaconservancy.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000017', 'c3000000-0000-4000-8000-000000000017', 'Improve a Neighborhood Park', 'environment', 'Volunteers help clean up, plant, and improve parks and greenspaces across metro Atlanta through Park Pride projects and volunteer days. It is easy, high-impact outdoor work that a group or class can do together. Check the site for upcoming workdays near you.', array['outdoors', 'physical work', 'good for crews'], 12, false, false, true, '2-3 hrs', 'https://parkpride.org/', 'https://parkpride.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000018', 'c3000000-0000-4000-8000-000000000018', 'Join a Community Cleanup', 'environment', 'Volunteers pitch in on litter cleanups, recycling drives, and beautification projects run by Keep Georgia Beautiful and its dozens of local affiliates statewide. It is a flexible, family-friendly way to make your own community cleaner. Find or start a project through their network.', array['outdoors', 'good for crews', 'family friendly'], 12, false, false, true, '2-3 hrs', 'https://keepgeorgiabeautiful.org/', 'https://keepgeorgiabeautiful.org/', '2026-01-01T00:00:00Z', 'Georgia', 'GA'),
  ('c4000000-0000-4000-8000-000000000019', 'c3000000-0000-4000-8000-000000000019', 'Sort Food for Coastal Georgia', 'food', 'Volunteers sort and box donated food at America''s Second Harvest of Coastal Georgia so it can reach partner agencies across 21 counties from Savannah. They welcome individuals, groups, and families and can work around your schedule. It is steady, rewarding work against local hunger.', array['good for crews', 'family friendly'], 12, false, false, true, '2-3 hrs', 'https://helpendhunger.org/volunteer/', 'https://helpendhunger.org/volunteer/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('c4000000-0000-4000-8000-000000000020', 'c3000000-0000-4000-8000-000000000020', 'Pack Food in Middle Georgia', 'food', 'Volunteers help pack and distribute food to neighbors in need at the Middle Georgia Community Food Bank in Macon, which welcomes individuals, work groups, and families. Expect light lifting and hands-on sorting. It is a great group project for a couple of hours.', array['good for crews', 'family friendly'], 12, false, false, true, '2-3 hrs', 'https://mgcfb.org/volunteer/', 'https://mgcfb.org/volunteer/', '2026-01-01T00:00:00Z', 'Macon', 'GA'),
  ('c4000000-0000-4000-8000-000000000021', 'c3000000-0000-4000-8000-000000000021', 'Serve a Meal in Athens', 'food', 'Volunteers help prepare and serve meals to more than 500 guests a week at Our Daily Bread community kitchen in Athens, part of Downtown Ministries. Groups sign up for shifts through the site. It is a warm, people-first way to help neighbors facing hard times.', array['good for crews', 'recurring'], 14, false, false, true, '2-3 hrs', 'https://downtownministries.org/our-daily-bread/', 'https://downtownministries.org/our-daily-bread/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('c4000000-0000-4000-8000-000000000022', 'c3000000-0000-4000-8000-000000000022', 'Welcome and Tutor New Americans', 'community', 'Volunteers tutor English, mentor youth, and help newly arrived refugee families settle in with New American Pathways in Atlanta. Roles range from one-time projects to a regular weekly commitment. It is a meaningful way to help someone build a new life in Georgia.', array['recurring', 'counts for school hours'], 16, false, false, true, '1-2 hrs / week', 'https://newamericanpathways.org/', 'https://newamericanpathways.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000023', 'c3000000-0000-4000-8000-000000000023', 'Support Refugee Families in Clarkston', 'community', 'Volunteers help with tutoring, wellness, employment, and youth programs for refugees resettled in Clarkston, one of the most diverse communities in the country. There are roles for individuals and groups, and it is welcoming to teens with a guardian. It is an eye-opening, rewarding place to serve.', array['recurring', 'family friendly', 'counts for school hours'], 14, false, false, true, '2-3 hrs', 'https://friendsofrefugees.com/', 'https://friendsofrefugees.com/', '2026-01-01T00:00:00Z', 'Clarkston', 'GA'),
  ('c4000000-0000-4000-8000-000000000024', 'c3000000-0000-4000-8000-000000000024', 'Help Homeless Families at Nicholas House', 'community', 'Volunteers cook and share meals, tutor kids, and help with projects at Nicholas House, the only Atlanta shelter that keeps homeless families together. There are hands-on and off-site roles for both individuals and large groups. It is a direct way to support families working toward stability.', array['recurring', 'good for crews', 'family friendly'], 13, false, false, true, '2-3 hrs', 'https://nicholashouse.org/volunteer/', 'https://nicholashouse.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000025', 'c3000000-0000-4000-8000-000000000025', 'Keep the ToolBank Running', 'community', 'Volunteers help organize, maintain, and check out tools at the Atlanta Community ToolBank, which lends tools to hundreds of other nonprofits and service groups. It is behind-the-scenes work that powers thousands of other volunteer projects each year. Great for a group looking for a hands-on shift.', array['good for crews', 'physical work'], 16, false, false, true, '2-3 hrs', 'https://www.atlantatoolbank.org/volunteer/', 'https://www.atlantatoolbank.org/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000026', 'c3000000-0000-4000-8000-000000000026', 'Serve Breakfast at Emmaus House', 'community', 'Volunteers help serve breakfast and hand out hygiene kits at the Emmaus House day center in downtown Savannah, run by United Ministries. Shifts run weekday mornings, and you sign up ahead through the website. It is a welcoming place to serve neighbors experiencing homelessness.', array['good for crews', 'recurring'], 16, false, false, true, '2-3 hrs', 'https://unitedministriessavannah.org/', 'https://unitedministriessavannah.org/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('c4000000-0000-4000-8000-000000000027', 'c3000000-0000-4000-8000-000000000027', 'Support Grieving Kids at Kate''s Club', 'community', 'Volunteers serve meals or provide hands-on support during Clubhouse programs where children and teens process grief through activities and community at Kate''s Club. Meal service needs no training, while program support requires a background screening. It is a caring role for anyone who wants to help kids through loss.', array['recurring', 'creative work'], 14, false, false, true, '2-3 hrs', 'https://www.katesclub.org/volunteer', 'https://www.katesclub.org/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000028', 'c3000000-0000-4000-8000-000000000028', 'Support Latino Families in Atlanta', 'community', 'Volunteers help with tutoring, English classes, workforce programs, and events at the Latin American Association, which empowers Latino families across Georgia. Bilingual volunteers are especially valued, but there is a role for everyone. It is a great fit if you want to support immigrant families directly.', array['recurring', 'counts for school hours'], 16, false, false, true, '1-2 hrs / week', 'https://thelaa.org/', 'https://thelaa.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000029', 'c3000000-0000-4000-8000-000000000029', 'Become a Big Brother or Big Sister', 'education', 'Volunteers are matched one-to-one with a child in central Georgia and spend a few hours together a couple of times a month, doing everyday activities that build confidence and trust. Big Brothers Big Sisters screens, trains, and supports every match at no cost. Because it is an ongoing relationship, expect a real, sustained commitment.', array['recurring', 'leadership role', 'counts for school hours'], 16, false, false, true, '2-4 hrs / month', 'https://bbbsheartga.org/', 'https://bbbsheartga.org/', '2026-01-01T00:00:00Z', 'Macon', 'GA'),
  ('c4000000-0000-4000-8000-000000000030', 'c3000000-0000-4000-8000-000000000030', 'Mentor a Student with the 100', 'education', 'Volunteers mentor and support underserved Atlanta students through Project Success and other 100 Black Men of Atlanta programs that guide young people toward college. Complete the volunteer form to be matched with opportunities through the year. It is a strong pick for a steady mentoring role.', array['recurring', 'leadership role', 'counts for school hours'], 16, false, false, true, '2-3 hrs', 'https://100blackmen-atlanta.org/how-to-help/volunteer.html', 'https://100blackmen-atlanta.org/how-to-help/volunteer.html', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000031', 'c3000000-0000-4000-8000-000000000031', 'Join a Ferst Readers Action Team', 'education', 'Volunteers join a local Community Action Team that raises funds and registers children so kids under five receive a free book in the mail each month. It is a flexible, behind-the-scenes way to boost early literacy in your own county. Great for anyone who believes every kid deserves books at home.', array['recurring', 'family friendly'], 13, false, false, true, '1-2 hrs / month', 'https://ferstreaders.org/', 'https://ferstreaders.org/', '2026-01-01T00:00:00Z', 'Georgia', 'GA'),
  ('c4000000-0000-4000-8000-000000000032', 'c3000000-0000-4000-8000-000000000032', 'Sort and Pack Books for Africa', 'education', 'Volunteers sort and pack donated books by category and age level at the Atlanta fulfillment center of Books for Africa, the largest shipper of donated books to the continent. No heavy lifting is involved, and volunteers should be at least 14. It is an easy, feel-good shift for individuals or groups.', array['good for crews', 'counts for school hours', 'family friendly'], 14, false, false, true, '2 hrs', 'https://www.booksforafrica.org/getting-involved/volunteer.html', 'https://www.booksforafrica.org/getting-involved/volunteer.html', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000033', 'c3000000-0000-4000-8000-000000000033', 'Tutor an Adult Learner', 'education', 'Volunteers help adults build reading, writing, math, and work skills through Literacy Action, the largest free adult-education nonprofit in Georgia. Training is provided, and it is a good fit if you want a consistent, one-on-one teaching relationship. Many college students, professionals, and retirees volunteer here.', array['recurring', 'counts for school hours'], 16, false, false, true, '1-2 hrs / week', 'https://literacyaction.org/', 'https://literacyaction.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000034', 'c3000000-0000-4000-8000-000000000034', 'Cook for Cancer Patients at Hope Lodge', 'medicine', 'Volunteers prepare and share meals and help create a comforting home for cancer patients and caregivers staying free of charge at the Atlanta Hope Lodge during treatment. Cooking a meal is a favorite group project. A warm dinner can mean the world to a family far from home.', array['recurring', 'family friendly', 'good for crews'], 16, false, false, true, '2-3 hrs', 'https://www.cancer.org/involved/volunteer/hope-lodge.html', 'https://www.cancer.org/involved/volunteer/hope-lodge.html', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000035', 'c3000000-0000-4000-8000-000000000035', 'Sort Medical Supplies at MedShare', 'medicine', 'Volunteers sort and package surplus medical supplies at MedShare so they can be shipped to hospitals and clinics in need around the world. Youth ages 10 to 17 are welcome with a signed parent permission form, making it one of the most family-friendly hands-on options around. Shifts are set on specific days, so book ahead.', array['good for crews', 'family friendly'], 10, false, false, true, '3 hrs', 'https://www.medshare.org/volunteer/atlanta/', 'https://www.medshare.org/volunteer/atlanta/', '2026-01-01T00:00:00Z', 'Decatur', 'GA'),
  ('c4000000-0000-4000-8000-000000000036', 'c3000000-0000-4000-8000-000000000036', 'Be a Fairy Godparent', 'medicine', 'Volunteers support children with chronic and terminal illnesses and their families year round through Bert''s Big Adventure''s Fairy Godparent program and reunion events. Volunteers must be 21 or older and pass a background check. It is a heartfelt role for adults who want to bring families joy during hard times.', array['recurring', 'family friendly'], 21, false, false, true, 'Varies', 'https://bertsbigadventure.org/get-involved/volunteer-locally/', 'https://bertsbigadventure.org/get-involved/volunteer-locally/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000037', 'c3000000-0000-4000-8000-000000000037', 'Support Youth Mental Health at CHRIS 180', 'medicine', 'Volunteers help with projects, events, and program support at CHRIS 180, a leading Atlanta mental-health and family-services nonprofit serving children and families. There are in-person and virtual roles for individuals and groups. It is a good fit if you care about trauma-informed care and youth well-being.', array['recurring', 'good for crews'], 16, false, false, true, '2-3 hrs', 'https://chris180.org/ways-to-volunteer/', 'https://chris180.org/ways-to-volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000038', 'c3000000-0000-4000-8000-000000000038', 'Support Families Facing Alzheimer''s', 'seniors', 'Volunteers help with support groups, education and awareness events, advocacy, and fundraising walks with the Alzheimer''s Association Georgia Chapter. Roles fit a range of interests and schedules, from one-time events to ongoing support. It is meaningful if your family has been touched by dementia.', array['recurring', 'leadership role'], 16, false, false, true, 'Varies', 'https://www.alz.org/georgia/volunteers', 'https://www.alz.org/georgia/volunteers', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000039', 'c3000000-0000-4000-8000-000000000039', 'Coach Youth Sports at the Y', 'sports', 'Volunteers coach kids in sports like soccer, basketball, and baseball at YMCA of Metro Atlanta branches, teaching fundamentals and good sportsmanship. Coaches complete a background check and short safety trainings, and hold about one practice and one game a week. It is a rewarding, recurring role close to home.', array['recurring', 'leadership role', 'family friendly'], 16, false, false, true, '2-3 hrs / week', 'https://www.ymcaatlanta.org/impact/volunteer', 'https://www.ymcaatlanta.org/impact/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000040', 'c3000000-0000-4000-8000-000000000040', 'Coach a Girls on the Run Team', 'sports', 'Volunteers coach a team of girls ages 8 to 14 twice a week for a 12-week season that blends running with life-skills lessons and ends in a celebratory 5K. You do not need to be a runner or a teacher - training and a full curriculum are provided. It is one of the most rewarding recurring roles for the season.', array['recurring', 'leadership role'], 16, false, false, true, '2-3 hrs / week', 'https://www.girlsontherunatlanta.org/volunteer', 'https://www.girlsontherunatlanta.org/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000041', 'c3000000-0000-4000-8000-000000000041', 'Coach Kids Through Golf', 'sports', 'Volunteers serve as coaches and mentors at First Tee - Metro Atlanta, using golf to teach kids character and life skills; you do not need to be a golfer, since training is provided. After applying, you complete youth-safety requirements and a background check. It is a steady, positive role model position for the season.', array['recurring', 'leadership role', 'outdoors'], 16, false, false, true, '2-3 hrs / week', 'https://firstteeatlanta.org/get-involved/volunteer/', 'https://firstteeatlanta.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000042', 'c3000000-0000-4000-8000-000000000042', 'Help Behind the Scenes at the Symphony', 'music', 'Volunteers assist with the box office, seat patrons, and support music-education events for the Georgia Symphony Orchestra and its large youth orchestra program in Marietta. It is a great fit if you love live music and want a behind-the-scenes view. Roles range from single concerts to a season-long commitment.', array['recurring', 'creative work'], 14, false, false, true, '3-4 hrs', 'https://www.georgiasymphony.org/employment-and-opportunities/', 'https://www.georgiasymphony.org/employment-and-opportunities/', '2026-01-01T00:00:00Z', 'Marietta', 'GA'),
  ('c4000000-0000-4000-8000-000000000043', 'c3000000-0000-4000-8000-000000000043', 'Teach or Mentor Young Musicians', 'music', 'Volunteers teach lessons, mentor students, or help run programs at ANAM Georgia, which uses music and the arts to develop young people across metro Atlanta. If you play an instrument, you can share that skill directly with a student. It is a meaningful way to pass music on to the next generation.', array['recurring', 'creative work', 'counts for school hours'], 14, false, false, true, '1-2 hrs / week', 'https://anamgeorgia.org/', 'https://anamgeorgia.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000044', 'c3000000-0000-4000-8000-000000000044', 'Serve a Meal or Ring a Bell', 'faith', 'Volunteers serve meals, sort donations, and help at events and holiday bell-ringing with The Salvation Army across the 13 metro Atlanta counties it serves. There are one-time and ongoing roles for individuals, families, and groups. It is a flexible, welcoming way to help neighbors in need.', array['good for crews', 'family friendly', 'recurring'], 13, false, false, true, '2-3 hrs', 'https://southernusa.salvationarmy.org/metro-atlanta/', 'https://southernusa.salvationarmy.org/metro-atlanta/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000045', 'c3000000-0000-4000-8000-000000000045', 'Serve Meals in Columbus', 'faith', 'Volunteers help prepare and serve meals, sort donated items, and support outreach at Valley Rescue Mission, a Christ-centered nonprofit serving people experiencing homelessness in Columbus. Flexible scheduling means individuals and groups can find a fit. It is welcoming to volunteers of every background.', array['good for crews', 'recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://www.valleyrescuemission.org/volunteer-with-us', 'https://www.valleyrescuemission.org/volunteer-with-us', '2026-01-01T00:00:00Z', 'Columbus', 'GA'),
  ('c4000000-0000-4000-8000-000000000046', 'c3000000-0000-4000-8000-000000000046', 'Support Veterans and Their Families', 'veterans', 'Volunteers support Wounded Warrior Project programs and events in the Atlanta area that serve post-9/11 veterans and their families, from community activities to fitness and career programs. It is a good fit if you want to give back to those who served. Reach out through the Atlanta location page to find current opportunities.', array['recurring', 'good for crews'], 18, false, false, true, 'Varies', 'https://www.woundedwarriorproject.org/mission/locations/atlanta-georgia', 'https://www.woundedwarriorproject.org/mission/locations/atlanta-georgia', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000047', 'c3000000-0000-4000-8000-000000000047', 'Respond to Disasters as a Greyshirt', 'disaster', 'Volunteers train and deploy with Team Rubicon to help communities recover from storms - sawing downed trees, clearing debris, mucking flooded homes, and tarping roofs, including long-running recovery work in Georgia. You register through Roll Call and sign up for training and operations. It is physical, meaningful, team-based work led by military veterans.', array['physical work', 'good for crews', 'leadership role'], 18, false, false, true, 'Varies', 'https://teamrubiconusa.org/how-to-get-involved/volunteer-with-us/', 'https://teamrubiconusa.org/how-to-get-involved/volunteer-with-us/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000048', 'c3000000-0000-4000-8000-000000000048', 'Help Storm Survivors Rebuild', 'disaster', 'Volunteers help storm survivors with clean-up, roof tarping, and home repairs and rebuilds through Inspiritus disaster relief across Georgia, with response and long-term recovery roles. No special skills are required for many tasks - just a willingness to work. It is a hands-on way to help neighbors get back home.', array['physical work', 'good for crews', 'recurring'], 16, false, false, true, 'Varies', 'https://weinspirit.org/volunteer', 'https://weinspirit.org/volunteer', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000049', 'c3000000-0000-4000-8000-000000000049', 'Mentor Students in Tech', 'tech', 'Volunteers connect with K-12 tech-education programs through Goodie Nation, mentoring students, advising programs, or sharing skills from the tech industry. It is a strong fit if you work in or study technology and want to open doors for the next generation. Roles vary, so check the site for current initiatives.', array['recurring', 'leadership role'], 16, false, false, true, 'Varies', 'https://goodienation.org/', 'https://goodienation.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('c4000000-0000-4000-8000-000000000050', 'c3000000-0000-4000-8000-000000000050', 'Facilitate a Girls Who Code Club', 'tech', 'Volunteers 18 and up lead a free after-school Girls Who Code club, guiding students through coding projects for a semester or full school year; facilitators can come from any background, not just tech. Plan for about 3 to 4 hours a week including prep. It is a high-impact way to close the gender gap in computer science.', array['recurring', 'leadership role', 'counts for school hours'], 18, false, false, true, '3-4 hrs / week', 'https://girlswhocode.com/get-involved', 'https://girlswhocode.com/get-involved', '2026-01-01T00:00:00Z', 'Atlanta', 'GA')
on conflict (id) do nothing;
